from trlib import emit
def blk(n, kind):
    # kind: 'gb' ground floor & basement, 'dp' duplex penthouse, 'p' penthouse
    if kind=='gb':
        return (f"Bloque {n}, planta baja y sótano", f"Bloc {n}, rez-de-chaussée et sous-sol", f"Blok {n}, begane grond & kelder")
    if kind=='dp':
        return (f"Bloque {n}, ático dúplex", f"Bloc {n}, penthouse duplex", f"Blok {n}, duplex penthouse")
    return (f"Bloque {n}, ático", f"Bloc {n}, penthouse", f"Blok {n}, penthouse")
